namespace svg;

internal class SvgPlanarInputEdge
{
    internal SvgPlanarEdge Edge; internal SvgIntersectionSegment Segment; internal int CommandIndex; internal int SubpathIndex; internal int Ordinal; internal bool Closing;
    internal SvgPlanarInputEdge(SvgPlanarEdge edge, SvgIntersectionSegment segment, int commandIndex, int subpathIndex, int ordinal, bool closing) { Edge = edge; Segment = segment; CommandIndex = commandIndex; SubpathIndex = subpathIndex; Ordinal = ordinal; Closing = closing; }
}

internal class SvgPlanarFlattenResult
{
    internal bool Success; internal SvgPlanarError Error; internal System.Collections.Generic.List<SvgPlanarInputEdge>? Edges;
    internal SvgPlanarFlattenResult(bool success, SvgPlanarError error, System.Collections.Generic.List<SvgPlanarInputEdge>? edges) { Success = success; Error = error; Edges = edges; }
}

internal class SvgPlanarPathFlattener
{
    SvgPathData? path; SvgPlanarOptions options; System.Collections.Generic.List<SvgPlanarInputEdge> edges; SvgPoint? subpathStart; SvgPoint? subpathEnd; int subpathIndex; int ordinal; bool hasDrawable;
    internal SvgPlanarPathFlattener(SvgPathData? normalized, SvgPlanarOptions planarOptions) { path = normalized; options = planarOptions; edges = new System.Collections.Generic.List<SvgPlanarInputEdge>(); subpathStart = null; subpathEnd = null; subpathIndex = -1; ordinal = 0; hasDrawable = false; }
    internal SvgPlanarFlattenResult Run()
    {
        int index = 0; while (index < (path ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Commands.Count) { SvgPathCommand command = path.Commands[index]; if (command.Kind == SvgPathCommandKind.MoveTo) { SvgPlanarError closeError = CloseImplicit(); if (closeError != SvgPlanarError.None) return Failure(closeError); subpathIndex = command.SubpathIndex; ordinal = 0; subpathStart = new SvgPoint(command.EndX, command.EndY); subpathEnd = subpathStart; hasDrawable = false; } else { SvgPlanarError error = AddCommand(command, index); if (error != SvgPlanarError.None) return Failure(error); } index = index + 1; }
        SvgPlanarError finalError = CloseImplicit(); if (finalError != SvgPlanarError.None) return Failure(finalError); return new SvgPlanarFlattenResult(true, SvgPlanarError.None, edges);
    }
    SvgPlanarError AddCommand(SvgPathCommand command, int commandIndex)
    {
        SvgFlattenOptions flattenOptions = new SvgFlattenOptions(); flattenOptions.Tolerance = options.Tolerance; flattenOptions.MaximumSubdivisionDepth = options.MaximumSubdivisionDepth; flattenOptions.MaximumSegments = options.MaximumEdges - edges.Count > 0 ? options.MaximumEdges - edges.Count : 1;
        SvgPoint start = new SvgPoint(command.StartX, command.StartY); SvgPoint end = new SvgPoint(command.EndX, command.EndY); SvgFlattenResult flat; SvgIntersectionSegment segment;
        if (command.Kind == SvgPathCommandKind.LineTo || command.Kind == SvgPathCommandKind.ClosePath) { SvgLineSegment line = new SvgLineSegment(start, end); flat = line.Flatten(flattenOptions); segment = new SvgIntersectionSegment(line); }
        else if (command.Kind == SvgPathCommandKind.QuadraticCurveTo) { SvgQuadraticBezier quadratic = new SvgQuadraticBezier(start, new SvgPoint(command.Values[0], command.Values[1]), end); flat = quadratic.Flatten(flattenOptions); segment = SvgIntersectionSegment.CreateQuadratic(quadratic); }
        else if (command.Kind == SvgPathCommandKind.CubicCurveTo) { SvgCubicBezier cubic = new SvgCubicBezier(start, new SvgPoint(command.Values[0], command.Values[1]), new SvgPoint(command.Values[2], command.Values[3]), end); flat = cubic.Flatten(flattenOptions); segment = SvgIntersectionSegment.CreateCubic(cubic); }
        else if (command.Kind == SvgPathCommandKind.ArcTo) { SvgArcOperationResult arc = new SvgArcGeometry().FromCommand(command); if (!arc.Success) return SvgPlanarError.NonFiniteResult; flat = (arc.Arc ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Flatten(flattenOptions); segment = SvgIntersectionSegment.CreateArc(arc.Arc); }
        else return SvgPlanarError.InvalidPath;
        if (!flat.Success) return Map(flat.Error); bool closing = command.Kind == SvgPathCommandKind.ClosePath; int pointIndex = 1; while (pointIndex < (flat.Points ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { if (edges.Count >= options.MaximumEdges) return SvgPlanarError.EdgeLimitExceeded; SvgFlattenedPoint a = flat.Points[pointIndex - 1]; SvgFlattenedPoint b = flat.Points[pointIndex]; SvgPlanarEdge edge = SvgPlanarEdge.Create(a.Point, b.Point, commandIndex, a.Amount, b.Amount); edges.Add(new SvgPlanarInputEdge(edge, segment, commandIndex, subpathIndex, ordinal, closing)); ordinal = ordinal + 1; pointIndex = pointIndex + 1; }
        subpathEnd = end; hasDrawable = true; if (closing) { subpathEnd = subpathStart; hasDrawable = false; } return SvgPlanarError.None;
    }
    SvgPlanarError CloseImplicit() { if (!hasDrawable || subpathStart == null || subpathEnd == null) return SvgPlanarError.None; hasDrawable = false; if (SvgPlanarMath.Distance(subpathStart, subpathEnd) <= options.Tolerance) return SvgPlanarError.None; if (edges.Count >= options.MaximumEdges) return SvgPlanarError.EdgeLimitExceeded; SvgLineSegment line = new SvgLineSegment(subpathEnd, subpathStart); edges.Add(new SvgPlanarInputEdge(new SvgPlanarEdge(subpathEnd, subpathStart, -1), new SvgIntersectionSegment(line), -1, subpathIndex, ordinal, true)); ordinal = ordinal + 1; return SvgPlanarError.None; }
    SvgPlanarFlattenResult Failure(SvgPlanarError error) { return new SvgPlanarFlattenResult(false, error, null); }
    static SvgPlanarError Map(SvgFlattenError error) { if (error == SvgFlattenError.SegmentLimitExceeded) return SvgPlanarError.EdgeLimitExceeded; if (error == SvgFlattenError.SubdivisionLimitExceeded) return SvgPlanarError.SubdivisionLimitExceeded; if (error == SvgFlattenError.InvalidArgument) return SvgPlanarError.InvalidArgument; return SvgPlanarError.NonFiniteResult; }
}

internal class SvgSelfIntersectionState
{
    System.Collections.Generic.List<SvgPlanarInputEdge>? edges; SvgPlanarOptions options; System.Collections.Generic.List<SvgPathSelfIntersection> results; int comparisons;
    internal SvgSelfIntersectionState(System.Collections.Generic.List<SvgPlanarInputEdge>? input, SvgPlanarOptions planarOptions) { edges = input; options = planarOptions; results = new System.Collections.Generic.List<SvgPathSelfIntersection>(); comparisons = 0; }
    internal SvgPathSelfIntersectionResult Run()
    {
        SvgIntersectionOptions intersectionOptions = new SvgPlanarGeometry().IntersectionOptions(options); int first = 0; while (first < (edges ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { int second = first + 1; while (second < edges.Count) { if (comparisons >= options.MaximumComparisons) return new SvgPlanarGeometry().SelfFailure(SvgPlanarError.ComparisonLimitExceeded, comparisons); comparisons = comparisons + 1; SvgPlanarInputEdge a = edges[first]; SvgPlanarInputEdge b = edges[second]; SvgIntersectionResult found = new SvgIntersections().Find(new SvgIntersectionSegment(new SvgLineSegment(a.Edge.Start, a.Edge.End)), new SvgIntersectionSegment(new SvgLineSegment(b.Edge.Start, b.Edge.End)), intersectionOptions); if (!found.Success) return new SvgPlanarGeometry().SelfFailure(Map(found.Error), comparisons); int index = 0; while (index < (found.Intersections ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { SvgIntersection intersection = found.Intersections[index]; if (!SharedAdjacentEndpoint(a, b, intersection.Point)) { SvgPlanarError error = Add(a, b, intersection); if (error != SvgPlanarError.None) return new SvgPlanarGeometry().SelfFailure(error, comparisons); } index = index + 1; } second = second + 1; } first = first + 1; }
        return new SvgPathSelfIntersectionResult(true, SvgPlanarError.None, results, comparisons);
    }
    SvgPlanarError Add(SvgPlanarInputEdge first, SvgPlanarInputEdge second, SvgIntersection intersection)
    {
        double firstAmount = first.Edge.StartAmount + (first.Edge.EndAmount - first.Edge.StartAmount) * intersection.FirstAmount; double secondAmount = second.Edge.StartAmount + (second.Edge.EndAmount - second.Edge.StartAmount) * intersection.SecondAmount; SvgIntersectionKind kind = Classify(first, second, firstAmount, secondAmount, intersection.Kind); int index = 0; while (index < results.Count) { SvgPathSelfIntersection existing = results[index]; if (existing.FirstCommandIndex == first.CommandIndex && existing.SecondCommandIndex == second.CommandIndex && SvgPlanarMath.Distance(existing.Point, intersection.Point) <= options.Tolerance) { existing.DuplicateCount = existing.DuplicateCount + 1 + intersection.DuplicateCount; if (kind == SvgIntersectionKind.Overlap) existing.Kind = SvgIntersectionKind.Overlap; else if (kind == SvgIntersectionKind.Tangent && existing.Kind == SvgIntersectionKind.Crossing) existing.Kind = SvgIntersectionKind.Tangent; return SvgPlanarError.None; } index = index + 1; }
        if (results.Count >= options.MaximumIntersections) return SvgPlanarError.IntersectionLimitExceeded; results.Add(new SvgPathSelfIntersection(new SvgPoint(intersection.Point.X, intersection.Point.Y), first.CommandIndex, second.CommandIndex, firstAmount, secondAmount, kind)); return SvgPlanarError.None;
    }
    SvgIntersectionKind Classify(SvgPlanarInputEdge first, SvgPlanarInputEdge second, double firstAmount, double secondAmount, SvgIntersectionKind kind) { if (kind == SvgIntersectionKind.Overlap) return kind; SvgVectorOperationResult a = new SvgIntersections().Derivative(first.Segment, firstAmount); SvgVectorOperationResult b = new SvgIntersections().Derivative(second.Segment, secondAmount); if (!a.Success || !b.Success) return kind; double firstLength = SvgPlanarMath.Hypotenuse((a.Vector ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).X, a.Vector.Y); double secondLength = SvgPlanarMath.Hypotenuse((b.Vector ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).X, b.Vector.Y); if (firstLength == 0 || secondLength == 0) return SvgIntersectionKind.Tangent; double cross = a.Vector.X / firstLength * (b.Vector.Y / secondLength) - a.Vector.Y / firstLength * (b.Vector.X / secondLength); return System.Math.Abs(cross) <= options.TangentTolerance ? SvgIntersectionKind.Tangent : SvgIntersectionKind.Crossing; }
    bool SharedAdjacentEndpoint(SvgPlanarInputEdge first, SvgPlanarInputEdge second, SvgPoint point)
    {
        if (first.SubpathIndex != second.SubpathIndex) return false; if (second.Ordinal == first.Ordinal + 1 && SvgPlanarMath.Distance(first.Edge.End, second.Edge.Start) <= options.Tolerance) return SvgPlanarMath.Distance(point, first.Edge.End) <= options.Tolerance; if (first.Ordinal == 0 && second.Closing && SvgPlanarMath.Distance(second.Edge.End, first.Edge.Start) <= options.Tolerance) return SvgPlanarMath.Distance(point, first.Edge.Start) <= options.Tolerance; return false;
    }
    static SvgPlanarError Map(SvgIntersectionError error) { if (error == SvgIntersectionError.ComparisonLimitExceeded) return SvgPlanarError.ComparisonLimitExceeded; if (error == SvgIntersectionError.IntersectionLimitExceeded) return SvgPlanarError.IntersectionLimitExceeded; if (error == SvgIntersectionError.SegmentLimitExceeded) return SvgPlanarError.EdgeLimitExceeded; if (error == SvgIntersectionError.SubdivisionLimitExceeded) return SvgPlanarError.SubdivisionLimitExceeded; if (error == SvgIntersectionError.InvalidArgument) return SvgPlanarError.InvalidArgument; return SvgPlanarError.NonFiniteResult; }
}

internal class SvgPlanarSplitState
{
    System.Collections.Generic.List<SvgPlanarEdge> input; SvgPlanarOptions options; System.Collections.Generic.List<System.Collections.Generic.List<double>> amounts; int comparisons; int intersections;
    internal SvgPlanarSplitState(System.Collections.Generic.List<SvgPlanarEdge> edges, SvgPlanarOptions planarOptions) { input = edges; options = planarOptions; amounts = new System.Collections.Generic.List<System.Collections.Generic.List<double>>(); comparisons = 0; intersections = 0; }
    internal SvgPlanarSplitResult Run()
    {
        int index = 0; while (index < input.Count) { System.Collections.Generic.List<double> values = new System.Collections.Generic.List<double>(); values.Add(0); values.Add(1); amounts.Add(values); index = index + 1; }
        SvgIntersectionOptions intersectionOptions = new SvgPlanarGeometry().IntersectionOptions(options); int first = 0; while (first < input.Count) { int second = first + 1; while (second < input.Count) { if (comparisons >= options.MaximumComparisons) return new SvgPlanarGeometry().SplitFailure(SvgPlanarError.ComparisonLimitExceeded, comparisons); comparisons = comparisons + 1; SvgIntersectionResult found = new SvgIntersections().Find(new SvgIntersectionSegment(new SvgLineSegment(input[first].Start, input[first].End)), new SvgIntersectionSegment(new SvgLineSegment(input[second].Start, input[second].End)), intersectionOptions); if (!found.Success) return new SvgPlanarGeometry().SplitFailure(Map(found.Error), comparisons); int hit = 0; while (hit < (found.Intersections ?? throw new System.InvalidOperationException("A required SVG value is unavailable.")).Count) { if (intersections >= options.MaximumIntersections) return new SvgPlanarGeometry().SplitFailure(SvgPlanarError.IntersectionLimitExceeded, comparisons); intersections = intersections + 1; AddAmount(amounts[first], found.Intersections[hit].FirstAmount); AddAmount(amounts[second], found.Intersections[hit].SecondAmount); hit = hit + 1; } second = second + 1; } first = first + 1; }
        System.Collections.Generic.List<SvgPlanarEdge> output = new System.Collections.Generic.List<SvgPlanarEdge>(); index = 0; while (index < input.Count) { Sort(amounts[index]); SvgPlanarEdge source = input[index]; double parameterTolerance = options.Tolerance / SvgPlanarMath.Length(source); int amountIndex = 1; while (amountIndex < amounts[index].Count) { double a = amounts[index][amountIndex - 1]; double b = amounts[index][amountIndex]; if (b - a > parameterTolerance) { if (output.Count >= options.MaximumEdges) return new SvgPlanarGeometry().SplitFailure(SvgPlanarError.EdgeLimitExceeded, comparisons); SvgPoint start = SvgPlanarMath.Point(source.Start, source.End, a); SvgPoint end = SvgPlanarMath.Point(source.Start, source.End, b); double sourceStart = source.StartAmount + (source.EndAmount - source.StartAmount) * a; double sourceEnd = source.StartAmount + (source.EndAmount - source.StartAmount) * b; output.Add(SvgPlanarEdge.Create(start, end, source.SourceIndex, sourceStart, sourceEnd)); } amountIndex = amountIndex + 1; } index = index + 1; }
        return new SvgPlanarSplitResult(true, SvgPlanarError.None, output, comparisons);
    }
    void AddAmount(System.Collections.Generic.List<double> values, double amount) { int index = 0; while (index < values.Count) { if (System.Math.Abs(values[index] - amount) <= 1e-12) return; index = index + 1; } values.Add(amount); }
    static void Sort(System.Collections.Generic.List<double> values) { int index = 1; while (index < values.Count) { double value = values[index]; int before = index - 1; while (before >= 0 && values[before] > value) { values[before + 1] = values[before]; before = before - 1; } values[before + 1] = value; index = index + 1; } }
    static SvgPlanarError Map(SvgIntersectionError error) { if (error == SvgIntersectionError.IntersectionLimitExceeded) return SvgPlanarError.IntersectionLimitExceeded; if (error == SvgIntersectionError.ComparisonLimitExceeded) return SvgPlanarError.ComparisonLimitExceeded; if (error == SvgIntersectionError.SegmentLimitExceeded) return SvgPlanarError.EdgeLimitExceeded; if (error == SvgIntersectionError.SubdivisionLimitExceeded) return SvgPlanarError.SubdivisionLimitExceeded; if (error == SvgIntersectionError.InvalidArgument) return SvgPlanarError.InvalidArgument; return SvgPlanarError.NonFiniteResult; }
}

internal class SvgContourReconstructionState
{
    System.Collections.Generic.List<SvgPlanarEdge> edges; SvgPlanarOptions options; bool[] used;
    internal SvgContourReconstructionState(System.Collections.Generic.List<SvgPlanarEdge> input, SvgPlanarOptions planarOptions) { edges = input; options = planarOptions; used = new bool[input.Count]; }
    internal SvgContourReconstructionResult Run()
    {
        System.Collections.Generic.List<SvgPlanarContour> contours = new System.Collections.Generic.List<SvgPlanarContour>(); int remaining = edges.Count; while (remaining > 0) { int seed = Seed(); if (seed < 0) break; SvgPlanarEdge first = edges[seed]; if (SvgPlanarMath.Length(first) <= options.Tolerance) return new SvgPlanarGeometry().ContourFailure(SvgPlanarError.InvalidArgument); System.Collections.Generic.List<SvgPoint> points = new System.Collections.Generic.List<SvgPoint>(); points.Add(new SvgPoint(first.Start.X, first.Start.Y)); points.Add(new SvgPoint(first.End.X, first.End.Y)); used[seed] = true; remaining = remaining - 1; SvgPoint start = first.Start; SvgPoint current = first.End; double incomingX = first.End.X - first.Start.X; double incomingY = first.End.Y - first.Start.Y; while (SvgPlanarMath.Distance(current, start) > options.Tolerance) { int next = Next(current, incomingX, incomingY); if (next < 0) return new SvgPlanarGeometry().ContourFailure(SvgPlanarError.OpenContour); SvgPlanarEdge edge = edges[next]; used[next] = true; remaining = remaining - 1; points.Add(new SvgPoint(edge.End.X, edge.End.Y)); incomingX = edge.End.X - edge.Start.X; incomingY = edge.End.Y - edge.Start.Y; current = edge.End; } points[points.Count - 1] = new SvgPoint(start.X, start.Y); double area = Area(points); if (!SvgFiniteMath.IsFinite(area)) return new SvgPlanarGeometry().ContourFailure(SvgPlanarError.NonFiniteResult); contours.Add(new SvgPlanarContour(points, area)); }
        Sort(contours); return new SvgContourReconstructionResult(true, SvgPlanarError.None, contours);
    }
    int Seed() { int selected = -1; int index = 0; while (index < edges.Count) { if (!used[index] && (selected < 0 || Compare(edges[index], edges[selected]) < 0)) selected = index; index = index + 1; } return selected; }
    int Next(SvgPoint current, double incomingX, double incomingY) { int selected = -1; double selectedTurn = 0; int index = 0; while (index < edges.Count) { if (!used[index] && SvgPlanarMath.Distance(current, edges[index].Start) <= options.Tolerance) { double outgoingX = edges[index].End.X - edges[index].Start.X; double outgoingY = edges[index].End.Y - edges[index].Start.Y; double turn = System.Math.Atan2(incomingX * outgoingY - incomingY * outgoingX, incomingX * outgoingX + incomingY * outgoingY); if (turn < 0) turn = turn + System.Math.PI * 2; if (selected < 0 || turn < selectedTurn || turn == selectedTurn && Compare(edges[index], edges[selected]) < 0) { selected = index; selectedTurn = turn; } } index = index + 1; } return selected; }
    static double Area(System.Collections.Generic.List<SvgPoint> points) { double twice = 0; int index = 1; while (index < points.Count) { twice = twice + points[index - 1].X * points[index].Y - points[index].X * points[index - 1].Y; index = index + 1; } return twice / 2; }
    static int Compare(SvgPlanarEdge a, SvgPlanarEdge b) { int start = SvgPlanarMath.Compare(a.Start, b.Start); if (start != 0) return start; int end = SvgPlanarMath.Compare(a.End, b.End); if (end != 0) return end; if (a.SourceIndex < b.SourceIndex) return -1; if (a.SourceIndex > b.SourceIndex) return 1; return 0; }
    static void Sort(System.Collections.Generic.List<SvgPlanarContour> contours) { int index = 1; while (index < contours.Count) { SvgPlanarContour value = contours[index]; int before = index - 1; while (before >= 0 && Compare(contours[before].Points[0], value.Points[0]) > 0) { contours[before + 1] = contours[before]; before = before - 1; } contours[before + 1] = value; index = index + 1; } }
    static int Compare(SvgPoint a, SvgPoint b) { return SvgPlanarMath.Compare(a, b); }
}

internal static class SvgPlanarMath
{
    internal static bool ValidPoint(SvgPoint point) { return point != null && SvgFiniteMath.IsFinite(point.X) && SvgFiniteMath.IsFinite(point.Y); }
    internal static bool Unit(double value) { return SvgFiniteMath.IsFinite(value) && value >= 0 && value <= 1; }
    internal static double Distance(SvgPoint a, SvgPoint b) { return Hypotenuse(b.X - a.X, b.Y - a.Y); }
    internal static double Length(SvgPlanarEdge edge) { return Distance(edge.Start, edge.End); }
    internal static SvgPoint Point(SvgPoint start, SvgPoint end, double amount) { SvgFiniteResult x = SvgFiniteMath.Lerp(start.X, end.X, amount); SvgFiniteResult y = SvgFiniteMath.Lerp(start.Y, end.Y, amount); return new SvgPoint(x.Value, y.Value); }
    internal static bool OnEdge(SvgPoint point, SvgPlanarEdge edge, double tolerance) { double scale = Scale(point, edge); double startX = edge.Start.X / scale; double startY = edge.Start.Y / scale; double endX = edge.End.X / scale; double endY = edge.End.Y / scale; double pointX = point.X / scale; double pointY = point.Y / scale; double dx = endX - startX; double dy = endY - startY; double lengthSquared = dx * dx + dy * dy; double amount = lengthSquared == 0 ? 0 : ((pointX - startX) * dx + (pointY - startY) * dy) / lengthSquared; if (amount < 0) amount = 0; else if (amount > 1) amount = 1; return Hypotenuse(pointX - (startX + amount * dx), pointY - (startY + amount * dy)) <= tolerance / scale; }
    internal static double Scale(SvgPoint point, SvgPlanarEdge edge) { double scale = AbsoluteHigh(edge.Start.X, edge.Start.Y); scale = Higher(scale, System.Math.Abs(edge.End.X)); scale = Higher(scale, System.Math.Abs(edge.End.Y)); scale = Higher(scale, System.Math.Abs(point.X)); scale = Higher(scale, System.Math.Abs(point.Y)); return scale == 0 ? 1 : scale; }
    internal static int Compare(SvgPoint a, SvgPoint b) { if (a.X < b.X) return -1; if (a.X > b.X) return 1; if (a.Y < b.Y) return -1; if (a.Y > b.Y) return 1; return 0; }
    internal static double Hypotenuse(double x, double y) { double ax = System.Math.Abs(x); double ay = System.Math.Abs(y); double high = ax > ay ? ax : ay; if (high == 0) return 0; double low = ax < ay ? ax : ay; double ratio = low / high; return high * System.Math.Sqrt(1 + ratio * ratio); }
    static double AbsoluteHigh(double a, double b) { return Higher(System.Math.Abs(a), System.Math.Abs(b)); }
    static double Higher(double a, double b) { return a > b ? a : b; }
}
